package com.stockpulse.entity;

import jakarta.persistence.*;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import lombok.Getter;
import com.stockpulse.entity.SuggestionStatus;
import com.stockpulse.entity.TriggerReason;
import lombok.Setter;
import lombok.NoArgsConstructor;
import lombok.AllArgsConstructor;

/**
 * Entity representing a reorder suggestion generated by the system.
 */
@Entity
@Table(name = "reorder_suggestions")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
public class ReorderSuggestion {
    
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    
    @NotNull(message = "Product is required")
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "product_id", nullable = false)
    private Product product;
    
    @NotNull(message = "Current stock is required")
    @Column(nullable = false)
    private Integer currentStock;
    
    @NotNull(message = "Recommended quantity is required")
    @Positive(message = "Recommended quantity must be positive")
    @Column(nullable = false)
    private Integer recommendedQuantity;
    
    @NotNull(message = "Suggested lead time is required")
    @Positive(message = "Suggested lead time must be positive")
    @Column(nullable = false)
    private Integer suggestedLeadTimeDays;
    
    @NotNull(message = "Confidence is required")
    @Column(nullable = false)
    private Double confidence; // Value between 0 and 1
    
    @Column(length = 1000)
    private String reasoning;
    
    @NotNull(message = "Status is required")
    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private SuggestionStatus status = SuggestionStatus.PENDING;
    
    @NotNull(message = "Trigger reason is required")
    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private TriggerReason triggerReason;
    
    @Column(name = "created_at", nullable = false, updatable = false)
    private java.time.LocalDateTime createdAt;
    
    @PrePersist
    protected void onCreate() {
        createdAt = java.time.LocalDateTime.now();
    }
}